    if (!li || li === dragEl || li.parentElement !== ul) return;

    const rect = li.getBoundingClientRect();
    const before = e.clientY - rect.top < rect.height / 2;
    ul.insertBefore(dragEl, before ? li : li.nextSibling);
  }

  function onUp() {
    if (!dragEl) return;
    dragEl.classList.remove("is-dragging");
    qsa(".is-over", ul).forEach((x) => x.classList.remove("is-over"));
    document.body.classList.remove("is-reordering");
    dragEl = null;
  }

  ul.addEventListener("pointerdown", (e) => {
    if (e.button !== undefined && e.button !== 0) return;
    const li = e.target.closest(".disc-item");
    if (!li || li.parentElement !== ul) return;

    const byTouch = e.pointerType === "touch" || e.pointerType === "pen";
    const fromHandle = !!e.target.closest(".disc-handle");
    if (byTouch && !fromHandle) return; // на тач-устройствах — только за handle

    e.preventDefault();
    dragEl = li;
    li.classList.add("is-dragging");
    document.body.classList.add("is-reordering");
    try { li.setPointerCapture(e.pointerId); } catch (_) {}
    li.addEventListener("pointermove", onMove);
    li.addEventListener("pointerup", onUp);
    li.addEventListener("pointercancel", onUp);
  });
}

